- (void)selectionChanged:(id)sender {NSInteger index=self.listTable.selectedRow;NSDictionary *choice=index>=0 && (NSUInteger)index<self.visibleChoices.count ? self.visibleChoices[index] : nil;NSDictionary *result=choice ? self.comparisons[[self choiceKey:choice]] : nil;if(result && !result[@"error"])[self acceptComparison:result];else {self.comparison=nil;[self.table reloadData];self.receiveButton.enabled=NO;self.status.stringValue=result[@"error"] ?: @"재생목록을 선택하세요.";self.versionLabel.stringValue=choice[@"name"] ?: @"재생목록";}}
- (void)publish:(id)sender {
