- (NSArray *)previewItems {NSMutableArray *items=[NSMutableArray arrayWithArray:self.comparison[@"manifest"][@"items"] ?: @[]];NSMutableSet *ids=[NSMutableSet set];for(NSDictionary *item in items)if(item[@"id"])[ids addObject:item[@"id"]];for(NSDictionary *old in self.comparison[@"localNode"][@"items"]){if(![old[@"tag"] isEqual:@"RVDocumentCue"] || [ids containsObject:old[@"attrs"][@"UUID"]])continue;[items addObject:@{@"name":old[@"attrs"][@"displayName"] ?: @"문서",@"kind":@"removed",@"path":old[@"attrs"][@"filePath"] ?: @""}];}return items;}
- (NSInteger)numberOfRowsInTableView:(NSTableView *)table {if(table==self.listTable)return self.visibleChoices.count;if(table==self.recoveryTable)return self.recoveryRecords.count;return self.previewItems.count;}
- (NSView *)tableView:(NSTableView *)table viewForTableColumn:(NSTableColumn *)column row:(NSInteger)index {
    NSString *text=@"",*tip=@"";NSColor *color=NSColor.labelColor;
    if(table==self.listTable){NSDictionary *choice=self.visibleChoices[index];NSString *state=[self comparisonStatus:self.comparisons[[self choiceKey:choice]]];text=[column.identifier isEqual:@"name"] ? choice[@"name"] : [column.identifier isEqual:@"status"] ? state : choice[@"date"];tip=[NSString stringWithFormat:@"%@ · %@",choice[@"path"],choice[@"date"]];if([column.identifier isEqual:@"date"] && text.length>=10)text=[text substringWithRange:NSMakeRange(5,5)];if([state isEqual:@"서버가 새로움"])color=[NSColor colorWithCalibratedRed:.18 green:.32 blue:.7 alpha:1];else if(![state isEqual:@"같음"])color=[NSColor colorWithCalibratedRed:.65 green:.3 blue:.1 alpha:1];}
